using System.Text.Json;using System.Text.RegularExpressions;using Npgsql;using SanSo.Api.Modules;using SanSo.Api.Security;
namespace SanSo.Api.V6;
public sealed record PersistentOnboardingView(string TenantId,int CurrentStep,string? SubjectType,string? LegalName,string? TaxIdentifierMasked,string? Address,string Currency,string TimeZone,string? SourceMode,DateOnly? BackfillFrom,int MappedSkuCount,IReadOnlyList<OpeningBalanceDraft> OpeningBalances,string? DisclaimerVersion,DateTimeOffset? DisclaimerConfirmedAt,string? FirstReconciliationId,DateTimeOffset? CompletedAt,DateTimeOffset UpdatedAt);
public sealed class PostgresOnboardingStoreV1(NpgsqlDataSource dataSource,TenantFieldProtector protector)
{
 static readonly Regex TaxId=new("^(?:[0-9]{10}|[0-9]{13})$",RegexOptions.Compiled|RegexOptions.CultureInvariant);
 public async Task<PersistentOnboardingView> Start(string tenant,CancellationToken ct){await using var c=await Open(tenant,ct);await using(var insert=c.CreateCommand()){insert.CommandText="INSERT INTO onboarding_profiles(organization_id)VALUES($1::uuid)ON CONFLICT(organization_id)DO NOTHING";insert.Parameters.AddWithValue(tenant);await insert.ExecuteNonQueryAsync(ct);}return await Get(c,tenant,ct);}
 public async Task<PersistentOnboardingView> SaveBusinessProfile(string tenant,BusinessProfileDraft profile,CancellationToken ct){if(string.IsNullOrWhiteSpace(profile.LegalName))throw new OnboardingValidationException("LEGAL_NAME_REQUIRED");if(!TaxId.IsMatch(profile.TaxIdentifier))throw new OnboardingValidationException("TAX_IDENTIFIER_FORMAT_INVALID");if(string.IsNullOrWhiteSpace(profile.Address))throw new OnboardingValidationException("ADDRESS_REQUIRED");if(profile.Currency!="VND")throw new OnboardingValidationException("MVP_CURRENCY_UNSUPPORTED");if(profile.TimeZone!="Asia/Ho_Chi_Minh")throw new OnboardingValidationException("MVP_TIMEZONE_UNSUPPORTED");await Start(tenant,ct);await using var c=await Open(tenant,ct);await using var q=c.CreateCommand();q.CommandText="UPDATE onboarding_profiles SET current_step=2,subject_type=$2,legal_name=$3,tax_identifier_protected=$4,tax_identifier_last4=$5,address_protected=$6,field_key_version=$7,currency=$8,timezone=$9,updated_at=now() WHERE organization_id=$1::uuid AND current_step=1";q.Parameters.AddWithValue(tenant);q.Parameters.AddWithValue(profile.SubjectType.ToString());q.Parameters.AddWithValue(profile.LegalName.Trim());q.Parameters.AddWithValue(protector.Protect(tenant,"tax_identifier",profile.TaxIdentifier));q.Parameters.AddWithValue(profile.TaxIdentifier[^4..]);q.Parameters.AddWithValue(protector.Protect(tenant,"address",profile.Address));q.Parameters.AddWithValue(KeyVersion(protector.Protect(tenant,"key_probe","x")));q.Parameters.AddWithValue(profile.Currency);q.Parameters.AddWithValue(profile.TimeZone);await One(q,ct);return await Get(c,tenant,ct);}
 public Task<PersistentOnboardingView> SelectSource(string tenant,SourceMode mode,CancellationToken ct)=>Step(tenant,2,3,"source_mode=$2",[mode.ToString()],ct);public Task<PersistentOnboardingView> SelectBackfill(string tenant,DateOnly from,CancellationToken ct){var today=DateOnly.FromDateTime(DateTime.UtcNow);if(from>today)throw new OnboardingValidationException("BACKFILL_FUTURE_DATE");if(from<today.AddYears(-2))throw new OnboardingValidationException("BACKFILL_RANGE_EXCEEDS_MVP");return Step(tenant,3,4,"backfill_from=$2",[from],ct);}public Task<PersistentOnboardingView> ConfirmSku(string tenant,int count,CancellationToken ct){if(count<0)throw new OnboardingValidationException("SKU_COUNT_INVALID");return Step(tenant,4,5,"mapped_sku_count=$2",[count],ct);}public Task<PersistentOnboardingView> OpeningBalances(string tenant,IReadOnlyList<OpeningBalanceDraft> balances,CancellationToken ct){if(balances.Any(x=>string.IsNullOrWhiteSpace(x.CanonicalSku)||x.OnHand<0||x.UnitCostMinor<0)||balances.GroupBy(x=>x.CanonicalSku,StringComparer.OrdinalIgnoreCase).Any(x=>x.Count()>1))throw new OnboardingValidationException("OPENING_BALANCE_INVALID");return Step(tenant,5,6,"opening_balances=$2::jsonb",[JsonSerializer.Serialize(balances)],ct);}public Task<PersistentOnboardingView> Disclaimer(string tenant,string version,string actor,bool confirmed,CancellationToken ct){if(!confirmed)throw new OnboardingValidationException("DISCLAIMER_CONFIRMATION_REQUIRED");if(string.IsNullOrWhiteSpace(version))throw new OnboardingValidationException("DISCLAIMER_VERSION_REQUIRED");return Step(tenant,6,7,"disclaimer_version=$2,disclaimer_confirmed_at=now(),disclaimer_confirmed_by=$3::uuid",[version,actor],ct);}public Task<PersistentOnboardingView> Complete(string tenant,string reconciliationId,bool accepted,CancellationToken ct){if(!accepted)throw new OnboardingValidationException("ACTIVATION_RESULT_REQUIRED");if(!Guid.TryParse(reconciliationId,out _))throw new OnboardingValidationException("RECONCILIATION_ID_REQUIRED");return Step(tenant,7,8,"first_reconciliation_id=$2::uuid,completed_at=now()",[reconciliationId],ct);}
 async Task<PersistentOnboardingView> Step(string tenant,int expected,int next,string assignments,object[] values,CancellationToken ct){await using var c=await Open(tenant,ct);await using var q=c.CreateCommand();q.CommandText=$"UPDATE onboarding_profiles SET current_step={next},{assignments},updated_at=now() WHERE organization_id=$1::uuid AND current_step={expected}";q.Parameters.AddWithValue(tenant);foreach(var value in values)q.Parameters.AddWithValue(value);await One(q,ct);return await Get(c,tenant,ct);}static async Task One(NpgsqlCommand q,CancellationToken ct){if(await q.ExecuteNonQueryAsync(ct)!=1)throw new OnboardingValidationException("ONBOARDING_STEP_OUT_OF_ORDER");}
 async Task<PersistentOnboardingView> Get(NpgsqlConnection c,string tenant,CancellationToken ct){await using var q=c.CreateCommand();q.CommandText="SELECT current_step,subject_type,legal_name,tax_identifier_last4,address_protected,currency,timezone,source_mode,backfill_from,mapped_sku_count,opening_balances,disclaimer_version,disclaimer_confirmed_at,first_reconciliation_id::text,completed_at,updated_at FROM onboarding_profiles WHERE organization_id=$1::uuid";q.Parameters.AddWithValue(tenant);await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new KeyNotFoundException("ONBOARDING_NOT_FOUND");var balances=JsonSerializer.Deserialize<List<OpeningBalanceDraft>>(r.GetString(10))??[];return new(tenant,r.GetInt32(0),Text(r,1),Text(r,2),r.IsDBNull(3)?null:$"******{r.GetString(3)}",r.IsDBNull(4)?null:protector.Unprotect(tenant,"address",r.GetString(4)),r.GetString(5),r.GetString(6),Text(r,7),r.IsDBNull(8)?null:r.GetFieldValue<DateOnly>(8),r.GetInt32(9),balances,Text(r,11),r.IsDBNull(12)?null:r.GetFieldValue<DateTimeOffset>(12),Text(r,13),r.IsDBNull(14)?null:r.GetFieldValue<DateTimeOffset>(14),r.GetFieldValue<DateTimeOffset>(15));}static string? Text(NpgsqlDataReader r,int i)=>r.IsDBNull(i)?null:r.GetString(i);async Task<NpgsqlConnection> Open(string tenant,CancellationToken ct){var c=await dataSource.OpenConnectionAsync(ct);await using var q=c.CreateCommand();q.CommandText="SELECT set_config('app.current_organization_id',$1,false)";q.Parameters.AddWithValue(tenant);await q.ExecuteNonQueryAsync(ct);return c;}static string KeyVersion(string protectedValue)=>protectedValue.Split('.')[0];
}
